import { AffectedEntities } from './affected-entities';
import { AttackAttackType } from './attack-attack-type';
import { AttackEntrypoint } from './attack-entrypoint';
import { AttackSecurityProblem } from './attack-security-problem';
import { AttackState } from './attack-state';
import { AttackTarget } from './attack-target';
import { AttackTechnology } from './attack-technology';
import { Attacker } from './attacker';
import { ManagementZone } from './management-zone';
import { RequestInformation } from './request-information';
import { Vulnerability } from './vulnerability';
/**
 * Describes an attack.
 */
export interface Attack {
    affectedEntities?: AffectedEntities;
    /**
     * The ID of the attack.
     */
    attackId?: string;
    attackTarget?: AttackTarget;
    attackType?: AttackAttackType;
    attacker?: Attacker;
    /**
     * The display ID of the attack.
     */
    displayId?: string;
    /**
     * The display name of the attack.
     */
    displayName?: string;
    entrypoint?: AttackEntrypoint;
    /**
     * A list of management zones which the affected entities belong to.
     */
    managementZones?: ManagementZone[];
    request?: RequestInformation;
    securityProblem?: AttackSecurityProblem;
    state?: AttackState;
    technology?: AttackTechnology;
    /**
     * The timestamp when the attack occurred.
     */
    timestamp?: number;
    vulnerability?: Vulnerability;
}
